from math import comb

def calculate_ratio(n):
    if n < 4:
        # g(G) = 0, f(G) = 0 (assuming we are discussing K_n)
        return None

    # f(K_n) = comb(n, 3)
    f_gn = comb(n, 3)
    # g(K_n) = comb(n, 4)
    g_gn = comb(n, 4)

    if f_gn == 0:
        return 0

    return (g_gn**3) / (f_gn**4)

ratios = {}
for n in range(4, 15):
    ratio = calculate_ratio(n)
    ratios[n] = ratio

print("K_n ratios:")
for n, r in ratios.items():
    print(f"n={n}: {r}")

