import math

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    return math.comb(n, k)

def R(n):
    if n < 4:
        return None # Not well-defined for n<4 since g(K_n) is 0 for n<4

    # f(K_n) = C(n, 3)
    f_kn = combinations(n, 3)

    # g(K_n) = C(n, 4)
    g_kn = combinations(n, 4)

    # R(n) = g(K_n)^3 / f(K_n)^4
    try:
        return (g_kn**3) / (f_kn**4)
    except ZeroDivisionError:
        return float('inf')

# Test small values
