def combinations(n, k):
    if k < 0 or k > n:
        return 0
    import math
    return math.factorial(n) // (math.factorial(k) * math.factorial(n - k))

def ratio_Kn(n):
    if n < 4:
        return 0.0
    f_G = combinations(n, 3)
    g_G = combinations(n, 4)

    # Ratio = g(G)^3 / f(G)^4
    if f_G == 0: # Should only happen for n < 3
        return float('inf') 
    return (g_G**3) / (f_G**4)

# Test K_n for n = 3 to 8
